// Differential checks of STArray02-faithful.js against Lean, generated by leanscript --check
import * as M from "./STArray02-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1([])", () => M.test1([]), "#[1, 1, 1, 1, 2, 3, 2, 3, 4, 1, 2, 3, 5, 6, 7]", false);
check("test1([]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([]), "#[1, 1, 1, 1, 2, 3, 2, 3, 4, 1, 2, 3, 5, 6, 7]", false);
check("test1([-7n])", () => M.test1([-7n]), "#[1, 1, 1, -7, 1, 2, 3, -7, -7, 2, 3, 4, 1, 2, 3, -7, 5, 6, 7]", false);
check("test1([-7n]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([-7n]), "#[1, 1, 1, -7, 1, 2, 3, -7, -7, 2, 3, 4, 1, 2, 3, -7, 5, 6, 7]", false);
check("test1([-7n, -1n, 0n])", () => M.test1([-7n, -1n, 0n]), "#[1, 1, 1, -7, -1, 0, 1, 2, 3, -7, -1, 0, -7, -1, 0, 2, 3, 4, 1, 2, 3, -7, -1, 0, 5, 6, 7]", false);
check("test1([-7n, -1n, 0n]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([-7n, -1n, 0n]), "#[1, 1, 1, -7, -1, 0, 1, 2, 3, -7, -1, 0, -7, -1, 0, 2, 3, 4, 1, 2, 3, -7, -1, 0, 5, 6, 7]", false);
check("test1([12n, 3n, 2n, 1n])", () => M.test1([12n, 3n, 2n, 1n]), "#[1, 1, 1, 12, 3, 2, 1, 1, 2, 3, 12, 3, 2, 1, 12, 3, 2, 1, 2, 3, 4, 1, 2, 3, 12, 3, 2, 1, 5, 6, 7]", false);
check("test1([12n, 3n, 2n, 1n]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([12n, 3n, 2n, 1n]), "#[1, 1, 1, 12, 3, 2, 1, 1, 2, 3, 12, 3, 2, 1, 12, 3, 2, 1, 2, 3, 4, 1, 2, 3, 12, 3, 2, 1, 5, 6, 7]", false);
check("test2([])", () => M.test2([]), "#[1, 2, 3, 5, 6, 7, 2, 3, 4, 1, 2, 3, 1, 1, 1]", false);
check("test2([]) twice", () => ((a0) => (M.test2(a0), M.test2(a0)))([]), "#[1, 2, 3, 5, 6, 7, 2, 3, 4, 1, 2, 3, 1, 1, 1]", false);
check("test2([-7n])", () => M.test2([-7n]), "#[1, 2, 3, -7, 5, 6, 7, -7, 2, 3, 4, 1, 2, 3, -7, -7, 1, 1, 1]", false);
check("test2([-7n]) twice", () => ((a0) => (M.test2(a0), M.test2(a0)))([-7n]), "#[1, 2, 3, -7, 5, 6, 7, -7, 2, 3, 4, 1, 2, 3, -7, -7, 1, 1, 1]", false);
check("test2([-7n, -1n, 0n])", () => M.test2([-7n, -1n, 0n]), "#[1, 2, 3, -7, -1, 0, 5, 6, 7, -7, -1, 0, 2, 3, 4, 1, 2, 3, -7, -1, 0, -7, -1, 0, 1, 1, 1]", false);
check("test2([-7n, -1n, 0n]) twice", () => ((a0) => (M.test2(a0), M.test2(a0)))([-7n, -1n, 0n]), "#[1, 2, 3, -7, -1, 0, 5, 6, 7, -7, -1, 0, 2, 3, 4, 1, 2, 3, -7, -1, 0, -7, -1, 0, 1, 1, 1]", false);
check("test2([12n, 3n, 2n, 1n])", () => M.test2([12n, 3n, 2n, 1n]), "#[1, 2, 3, 12, 3, 2, 1, 5, 6, 7, 12, 3, 2, 1, 2, 3, 4, 1, 2, 3, 12, 3, 2, 1, 12, 3, 2, 1, 1, 1, 1]", false);
check("test2([12n, 3n, 2n, 1n]) twice", () => ((a0) => (M.test2(a0), M.test2(a0)))([12n, 3n, 2n, 1n]), "#[1, 2, 3, 12, 3, 2, 1, 5, 6, 7, 12, 3, 2, 1, 2, 3, 4, 1, 2, 3, 12, 3, 2, 1, 12, 3, 2, 1, 1, 1, 1]", false);

console.log(`STArray02-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
